  external double gen_tps;

  @ffi.Bool()
  external bool stopped_by_eos;

  @ffi.Bool()
  external bool stopped_by_user;
}

/// ------------------------------------------------------------------ */
/// /* Logging                                                             */
/// /* ------------------------------------------------------------------
enum kiln_log_level {
  KILN_LOG_ERROR(0),
  KILN_LOG_WARN(1),
  KILN_LOG_INFO(2),
  KILN_LOG_DEBUG(3);

  final int value;
  const kiln_log_level(this.value);

  static kiln_log_level fromValue(int value) => switch (value) {
    0 => KILN_LOG_ERROR,
    1 => KILN_LOG_WARN,
    2 => KILN_LOG_INFO,
    3 => KILN_LOG_DEBUG,
    _ => throw ArgumentError('Unknown value for kiln_log_level: $value'),
  };
}

typedef kiln_log_cbFunction =
    ffi.Void Function(
      ffi.UnsignedInt level,
      ffi.Pointer<ffi.Char> msg,
      ffi.Pointer<ffi.Void> user,
    );
typedef Dartkiln_log_cbFunction =
    void Function(
      kiln_log_level level,
      ffi.Pointer<ffi.Char> msg,
      ffi.Pointer<ffi.Void> user,
    );
typedef kiln_log_cb = ffi.Pointer<ffi.NativeFunction<kiln_log_cbFunction>>;

const int KILN_VERSION_MAJOR = 0;

const int KILN_VERSION_MINOR = 1;

const int KILN_VERSION_PATCH = 0;
